@Mod.EventBusSubscriber(modid=Thaumcraft.MODID)
public final class ScoutClient {
 static final BlockPos Q=new BlockPos(780,205,8);static int ticks,stage;static long due;static WorkerGolem g,scout;static SealEntity provider,dest,sentinel;static ChestBlockEntity source,target,outside;static GolemBuilder builder;
 static WorkerGolem spawn(ServerPlayer p,int head,int legs){var g=LogisticsClient.spawn(p,new GolemDesign(3,head,0,3,legs),Q);g.setCustomName(Component.literal("Scout "+head));return g;}
 static void snapshot(ServerPlayer p){var design=g.design();var out=TagValueOutput.createWithContext(ProblemReporter.DISCARDING,p.registryAccess());g.saveWithoutId(out);var copy=new WorkerGolem(GolemContent.GOLEM.get(),p.level());copy.load(TagValueInput.create(ProblemReporter.DISCARDING,p.registryAccess(),out.buildResult()));check(copy.design().equals(design)&&copy.head()==3&&copy.workRadius()==48&&copy.cargo.getItem(0).getCount()==23&&copy.delivery().equals(dest.getBlockPos()),"Scout snapshot lost head/radius/route/cargo");g.discard();copy.setUUID(UUID.randomUUID());g=copy;check(p.level().addFreshEntity(g),"Cannot restore Scout delivery");}
 @SubscribeEvent public static void tick(TickEvent.ServerTickEvent.Post e){if(!System.getProperty("thaumcraft.thaumaturgyProbe","").equals("scout-client")||e.server().isDedicatedServer()||e.server().getPlayerList().getPlayers().isEmpty()||++ticks<80)return;var p=e.server().getPlayerList().getPlayers().getFirst();var l=p.level();long now=l.getGameTime();
 if(stage==0){var r=l.recipeAccess().getRecipes().stream().map(h->h.value()).filter(v->v instanceof thaumcraft.crafting.ArcaneRecipe a&&a.research().equals("GOLEMVISION")).map(v->(thaumcraft.crafting.ArcaneRecipe)v).findFirst().orElseThrow();var input=net.minecraft.world.item.crafting.CraftingInput.of(3,3,List.of(new ItemStack(Items.GLASS_BOTTLE),ItemStack.EMPTY,new ItemStack(Items.GLASS_BOTTLE),new ItemStack(Items.FERMENTED_SPIDER_EYE),ItemStack.EMPTY,new ItemStack(Items.FERMENTED_SPIDER_EYE),item("plate_brass"),item("mechanism_simple"),item("plate_brass")));check(r.vis()==50&&r.crystals().get("aqua")==1&&r.matches(input,l)&&r.assemble(input).is(thaumcraft.content.SimpleContent.ITEMS.get("module_vision").get()),"Vision recipe/payment invalid");knowledge(p);p.getInventory().clearContent();p.setGameMode(GameType.SURVIVAL);for(int x=45;x<=53;x++)for(int z=-1;z<=1;z++)l.setChunkForced(x,z,true);for(var w:l.getEntitiesOfClass(WorkerGolem.class,new AABB(Q).inflate(60)))w.discard();for(var q:BlockPos.betweenClosed(Q.offset(-52,0,-4),Q.offset(52,5,4)))l.setBlockAndUpdate(q,Blocks.AIR.defaultBlockState());for(var q:BlockPos.betweenClosed(Q.offset(-52,-1,-4),Q.offset(52,-1,4)))l.setBlockAndUpdate(q,Blocks.STONE.defaultBlockState());provider=GolemClient.chestSeal(p,SealKind.PROVIDER,Q.west(39));source=(ChestBlockEntity)l.getBlockEntity(provider.support());source.clearContent();source.setItem(0,new ItemStack(Items.EMERALD,23));dest=GolemClient.chestSeal(p,SealKind.STOCK,Q.east(43));target=(ChestBlockEntity)l.getBlockEntity(dest.support());target.clearContent();dest.sample(0,new ItemStack(Items.EMERALD));dest.amounts[0]=23;sentinel=GolemClient.chestSeal(p,SealKind.STOCK,Q.east(50));outside=(ChestBlockEntity)l.getBlockEntity(sentinel.support());outside.clearContent();sentinel.sample(0,new ItemStack(Items.EMERALD));sentinel.priority=5;p.teleportTo(l,Q.getX()+.5,Q.getY(),Q.getZ()-3.5,Set.of(),0,0,true);stage=1;due=now+60;Thaumcraft.LOGGER.info("SCOUT_RECIPE_OK");return;}
 if(stage==1&&now>=due){g=spawn(p,1,0);stage=2;due=now+60;return;}
 if(stage==2&&now>=due){check(GolemClient.count(source,Items.EMERALD)==23&&g.cargo.isEmpty()&&g.delivery()==null&&GolemClient.count(target,Items.EMERALD)==0,"Old head used out-of-range seals");g.discard();g=spawn(p,3,0);check(g.workRadius()==48&&!g.design().has("smart")&&g.getAttributeValue(Attributes.FOLLOW_RANGE)==56,"Scout native range/traits invalid");provider.channel=1;stage=3;due=now+60;Thaumcraft.LOGGER.info("SCOUT_OLD_RADIUS_OK: ordinary Smart head cannot use the loaded 40/42-block route");return;}
 if(stage==3&&now>=due){check(GolemClient.count(source,Items.EMERALD)==23&&g.cargo.isEmpty(),"Scout ignored provider channel");provider.channel=0;stage=4;due=now+900;return;}
 if(stage==4){check(now<due,"Scout provider timeout "+g.position());if(g.delivery()==null)return;check(GolemClient.count(source,Items.EMERALD)==0&&g.cargo.getItem(0).getCount()==23,"Scout did not extract physical request");snapshot(p);l.setBlockAndUpdate(dest.getBlockPos().north(),Blocks.REDSTONE_BLOCK.defaultBlockState());stage=5;due=now+60;return;}
 if(stage==5&&now>=due){check(g.cargo.getItem(0).getCount()==23&&GolemClient.count(target,Items.EMERALD)==0,"Paused distant scout lost/teleported cargo");l.removeBlock(dest.getBlockPos().north(),false);stage=6;due=now+1000;return;}
 if(stage==6){check(now<due,"Scout distant delivery timeout "+g.position()+" cargo="+g.cargo.getItem(0));if(GolemClient.count(target,Items.EMERALD)!=23)return;check(g.cargo.isEmpty()&&outside.isEmpty(),"Scout overstocked outside radius or duplicated cargo");GolemClient.remove(provider);GolemClient.remove(dest);dest=GolemClient.chestSeal(p,SealKind.FILL_ADVANCED,Q.east(43));dest.filter=new ItemStack(Items.GOLD_INGOT);g.cargo.setItem(0,new ItemStack(Items.GOLD_INGOT,13));stage=7;due=now+60;Thaumcraft.LOGGER.info("SCOUT_ROUTE_OK: physical provider at 40 and stock at 42, 23 items, saved route, pause, channel and 49-block sentinel");return;}
 if(stage==7&&now>=due){check(g.cargo.getItem(0).getCount()==13&&GolemClient.count(target,Items.GOLD_INGOT)==0,"Clockwork Scout used a Smart-only advanced seal");g.setMode(2);scout=g;g=spawn(p,4,1);g.cargo.setItem(0,new ItemStack(Items.GOLD_INGOT,7));stage=8;due=now+700;return;}
 if(stage==8){check(now<due,"Smart Scout advanced delivery timeout "+g.position());if(GolemClient.count(target,Items.GOLD_INGOT)!=7)return;check(g.cargo.isEmpty()&&scout.cargo.getItem(0).getCount()==13&&GolemClient.count(target,Items.EMERALD)==23,"Smart Scout advanced delivery changed cargo");g.setMode(2);scout.setHealth(5);var design=scout.design();p.setItemInHand(InteractionHand.MAIN_HAND,item("golem_bell"));p.setShiftKeyDown(true);check(scout.interact(p,InteractionHand.MAIN_HAND,Vec3.ZERO)==InteractionResult.SUCCESS&&scout.isRemoved(),"Scout bell packing failed");p.setShiftKeyDown(false);var pack=java.util.stream.IntStream.range(0,36).mapToObj(i->p.getInventory().getItem(i)).filter(s->s.getItem() instanceof GolemPlacer&&s.get(GolemContent.DESIGN.get()).head()==3).findFirst().orElseThrow();check(pack.get(GolemContent.DESIGN.get()).equals(design)&&Math.abs(pack.get(GolemContent.HEALTH.get())-5F/16)<.001,"Scout packing lost head or healed");check(l.getEntitiesOfClass(ItemEntity.class,new AABB(scout.blockPosition()).inflate(3),x->x.getItem().is(Items.GOLD_INGOT)&&x.getItem().getCount()==13).size()==1,"Scout packing lost/duplicated cargo");Thaumcraft.LOGGER.info("SCOUT_SMART_PACK_OK: ordinary Scout rejects advanced seal, wheeled Smart Scout delivers seven; packed head/health and 13 cargo conserved");GolemClient.remove(dest);GolemClient.remove(sentinel);l.setBlockAndUpdate(Q.west(2),GolemContent.BUILDER.get().defaultBlockState());builder=(GolemBuilder)l.getBlockEntity(Q.west(2));builder.draft=GolemDesign.BASIC;GolemProbe.giveComponents(p,new GolemDesign(0,4,0,0));p.teleportTo(l,Q.getX()-1.5,Q.getY(),Q.getZ()-.5,Set.of(),0,0,true);p.openMenu(builder);stage=9;return;}
 if(stage==9&&builder.working()){check(builder.draft.head()==4&&!builder.edit(p,1),"Native GUI failed paid Smart Scout lock");stage=10;Thaumcraft.LOGGER.info("SCOUT_CLIENT_OK: native long route, Smart distinction, persistence, bell and paid GUI build");}
 }
}
